package edu.gcu.cst339.lab2_chinook_api.employee;

import java.time.LocalDateTime;

import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * Data transfer object used as the JSON request and response body for employees.
 *
 * <p>The validation annotations are checked when a request body is marked
 * {@code @Valid} in the controller.</p>
 *
 * @param employeeId the employee ID; generated by the database, so it is
 *                   ignored on create and taken from the URL on update
 * @param lastName   last name; required, at most 20 characters
 * @param firstName  first name; required, at most 20 characters
 * @param title      job title; optional, at most 30 characters
 * @param reportsTo  ID of the employee's manager; optional, but must reference
 *                   an existing employee if supplied
 * @param birthDate  date and time of birth; optional
 * @param hireDate   date and time of hire; optional
 * @param address    street address; optional, at most 70 characters
 * @param city       city; optional, at most 40 characters
 * @param state      state or province; optional, at most 40 characters
 * @param country    country; optional, at most 40 characters
 * @param postalCode postal code; optional, at most 10 characters
 * @param phone      phone number; optional, at most 24 characters
 * @param fax        fax number; optional, at most 24 characters
 * @param email      email address; optional, must be a valid address, at most 60 characters
 */
public record EmployeeDto(
    Integer employeeId,
        @NotBlank @Size(max = 20) String lastName,
        @NotBlank @Size(max = 20) String firstName,
        @Size(max = 30) String title,
        Integer reportsTo,
        LocalDateTime birthDate,
        LocalDateTime hireDate,
        @Size(max = 70) String address,
        @Size(max = 40) String city,
        @Size(max = 40) String state,
        @Size(max = 40) String country,
        @Size(max = 10) String postalCode,
        @Size(max = 24) String phone,
        @Size(max = 24) String fax,
        @Email @Size(max = 60) String email) {

    /**
     * Converts an employee entity into a DTO.
     *
     * @param e the entity to convert
     * @return a DTO containing all of the entity's fields
     */
    static EmployeeDto fromEntity(Employee e) {
        return new EmployeeDto(
                e.getEmployeeId(),
                e.getLastName(),
                e.getFirstName(),
                e.getTitle(),
                e.getReportsTo(),
                e.getBirthDate(),
                e.getHireDate(),
                e.getAddress(),
                e.getCity(),
                e.getState(),
                e.getCountry(),
                e.getPostalCode(),
                e.getPhone(),
                e.getFax(),
                e.getEmail());
    }
}
